  root.HAVKAR_UI_I18N21 = {
    selectable: SELECTABLE,
    glossaries: GLOSSARIES,
    pack: function (language) {
      var code = String(language || "en");
      if (code === "en") return {};
      var out = {};
      Object.keys(GLOSSARIES).forEach(function (section) {
        var row = GLOSSARIES[section][code];
        if (row) Object.assign(out, row);
      });
      return out;
    }
  };

